from pathlib import Path

path = Path('components/WorkflowWorkspaceV2.tsx')
text = path.read_text()

text = text.replace('import { BriefcaseBusiness, CalendarDays, Check, ChevronLeft, ChevronRight, Clock3, MapPin, ShieldCheck } from "lucide-react";', 'import { BriefcaseBusiness, CalendarDays, Check, ChevronRight, Clock3, MapPin, ShieldCheck } from "lucide-react";', 1)

old_type = 'type ProfessionalView = "overview" | "shifts" | "bookings" | "talent" | "profile";'
new_type = old_type + '\ntype CalendarView = "month" | "list";'
if old_type not in text:
    raise SystemExit('ProfessionalView type not found')
text = text.replace(old_type, new_type, 1)

old_state = '  const [calendarOffsetDays, setCalendarOffsetDays] = useState(0);\n  const [availabilityOpen, setAvailabilityOpen] = useState(false);'
new_state = '  const [calendarOffsetDays, setCalendarOffsetDays] = useState(0);\n  const [calendarView, setCalendarView] = useState<CalendarView>("month");\n  const [availabilityOpen, setAvailabilityOpen] = useState(false);'
if old_state not in text:
    raise SystemExit('Calendar state anchor not found')
text = text.replace(old_state, new_state, 1)

text = text.replace('  const canGoBack = calendarOffsetDays > 0;\n', '', 1)
text = text.replace('  const goCalendarBack = () => setCalendarOffsetDays((value) => Math.max(0, value - CALENDAR_PAGE_DAYS));\n', '', 1)

old_controls = '''        <div className="mt-4 flex flex-wrap items-center gap-2">\n          <button type="button" disabled={!canGoBack} onClick={goCalendarBack} className="secondary-btn disabled:cursor-not-allowed disabled:opacity-40" aria-label="Previous 35 days"><ChevronLeft size={16} />Previous</button>\n          <button type="button" onClick={goCalendarToday} className="secondary-btn">Today</button>\n          <button type="button" disabled={!canGoForward} onClick={goCalendarForward} className="secondary-btn disabled:cursor-not-allowed disabled:opacity-40" aria-label="Next 35 days">Next<ChevronRight size={16} /></button>\n          <button type="button" onClick={() => setAvailabilityOpen(true)} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#04A62F] px-4 py-2 text-sm font-black text-white shadow-sm transition hover:bg-[#038c28] focus:outline-none focus:ring-2 focus:ring-[#04A62F]/30"><CalendarDays size={18} />Post Availability</button>\n          <button type="button" onClick={() => { window.localStorage.setItem("dentalshift_portal_role", "professional"); window.location.href = "/classifieds?post=professional"; }} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#002757] px-4 py-2 text-sm font-black text-white shadow-sm transition hover:bg-[#001f46] focus:outline-none focus:ring-2 focus:ring-[#002757]/25"><BriefcaseBusiness size={18} />Post a Position</button>\n        </div>'''

new_controls = '''        <div className="mt-4 flex flex-wrap items-center gap-2">\n          <button type="button" onClick={goCalendarToday} className="secondary-btn">Today</button>\n          <button type="button" disabled={!canGoForward} onClick={goCalendarForward} className="secondary-btn disabled:cursor-not-allowed disabled:opacity-40" aria-label="Next 35 days">Next<ChevronRight size={16} /></button>\n          <div className="grid grid-cols-2 rounded-xl bg-slate-100 p-1">\n            {(["month", "list"] as CalendarView[]).map((mode) => <button key={mode} type="button" onClick={() => setCalendarView(mode)} className={`rounded-lg px-3 py-2 text-sm font-extrabold capitalize transition ${calendarView === mode ? "bg-[#0078FE] text-white shadow-sm" : "text-slate-600 hover:text-[#002757]"}`}>{mode === "month" ? "Calendar" : "List"}</button>)}\n          </div>\n          <button type="button" onClick={() => setAvailabilityOpen(true)} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#04A62F] px-4 py-2 text-sm font-black text-white shadow-sm transition hover:bg-[#038c28] focus:outline-none focus:ring-2 focus:ring-[#04A62F]/30"><CalendarDays size={18} />Post Availability</button>\n          <button type="button" onClick={() => { window.localStorage.setItem("dentalshift_portal_role", "professional"); window.location.href = "/classifieds?post=professional"; }} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#002757] px-4 py-2 text-sm font-black text-white shadow-sm transition hover:bg-[#001f46] focus:outline-none focus:ring-2 focus:ring-[#002757]/25"><BriefcaseBusiness size={18} />Post a Position</button>\n        </div>'''

if old_controls not in text:
    raise SystemExit('Professional controls block not found')
text = text.replace(old_controls, new_controls, 1)

old_calendar_open = '      <div className="grid lg:grid-cols-[minmax(0,1.45fr)_minmax(340px,.75fr)]">'
new_calendar_open = '''      {calendarView === "list" ? <div className="grid gap-4 p-4 sm:p-5 lg:grid-cols-3">\n        <section><h3 className="text-lg font-black text-[#002757]">Open shifts</h3><div className="mt-3 space-y-3">{matchingOpen.length ? matchingOpen.slice().sort((a, b) => new Date(a.starts_at).getTime() - new Date(b.starts_at).getTime()).map((shift) => <button type="button" key={shift.id} onClick={() => { const date = new Date(shift.starts_at); setSelectedDate(localDateKey(date)); setCalendarOffsetDays(Math.max(0, Math.floor((date.getTime() - new Date().setHours(12,0,0,0)) / 86400000 / CALENDAR_PAGE_DAYS) * CALENDAR_PAGE_DAYS)); setCalendarView("month"); }} className="w-full rounded-2xl border border-slate-200 p-4 text-left transition hover:bg-slate-50"><div className="flex items-center justify-between gap-2"><strong className="text-[#002757]">{shift.profession}</strong><span className="rounded-full bg-blue-50 px-2 py-1 text-[10px] font-black text-[#2f6fd0]">Open</span></div><p className="mt-1 text-xs text-slate-500">{new Date(shift.starts_at).toLocaleDateString("en-CA", { weekday: "short", month: "short", day: "numeric" })} · {shortTime(shift.starts_at)}–{shortTime(shift.ends_at)}</p><p className="mt-1 text-xs font-black text-[#002757]">${Number(shift.hourly_rate)}/hr</p></button>) : <p className="rounded-2xl bg-slate-50 p-5 text-sm text-slate-500">No open shifts right now.</p>}</div></section>\n        <section><h3 className="text-lg font-black text-[#002757]">Interested</h3><div className="mt-3 space-y-3">{applied.length ? applied.slice().sort((a, b) => new Date(a.shifts!.starts_at).getTime() - new Date(b.shifts!.starts_at).getTime()).map((application) => application.shifts ? <button type="button" key={application.id} onClick={() => { const date = new Date(application.shifts!.starts_at); setSelectedDate(localDateKey(date)); setCalendarOffsetDays(Math.max(0, Math.floor((date.getTime() - new Date().setHours(12,0,0,0)) / 86400000 / CALENDAR_PAGE_DAYS) * CALENDAR_PAGE_DAYS)); setCalendarView("month"); }} className="w-full rounded-2xl border border-slate-200 p-4 text-left transition hover:bg-slate-50"><div className="flex items-center justify-between gap-2"><strong className="text-[#002757]">{application.shifts.profession}</strong><span className="rounded-full bg-green-50 px-2 py-1 text-[10px] font-black text-[#278841]">Interested</span></div><p className="mt-1 text-xs text-slate-500">{new Date(application.shifts.starts_at).toLocaleDateString("en-CA", { weekday: "short", month: "short", day: "numeric" })} · {shortTime(application.shifts.starts_at)}–{shortTime(application.shifts.ends_at)}</p></button> : null) : <p className="rounded-2xl bg-slate-50 p-5 text-sm text-slate-500">No active interests right now.</p>}</div></section>\n        <section><h3 className="text-lg font-black text-[#002757]">Confirmed bookings</h3><div className="mt-3 space-y-3">{booked.length ? booked.slice().sort((a, b) => new Date(a.shifts!.starts_at).getTime() - new Date(b.shifts!.starts_at).getTime()).map((booking) => booking.shifts ? <button type="button" key={booking.id} onClick={() => { const date = new Date(booking.shifts!.starts_at); setSelectedDate(localDateKey(date)); setCalendarOffsetDays(Math.max(0, Math.floor((date.getTime() - new Date().setHours(12,0,0,0)) / 86400000 / CALENDAR_PAGE_DAYS) * CALENDAR_PAGE_DAYS)); setCalendarView("month"); }} className="w-full rounded-2xl border border-slate-200 p-4 text-left transition hover:bg-slate-50"><div className="flex items-center justify-between gap-2"><strong className="text-[#002757]">{booking.shifts.profession}</strong><span className="rounded-full bg-[#002757] px-2 py-1 text-[10px] font-black text-white">Booked</span></div><p className="mt-1 text-xs text-slate-500">{new Date(booking.shifts.starts_at).toLocaleDateString("en-CA", { weekday: "short", month: "short", day: "numeric" })} · {shortTime(booking.shifts.starts_at)}–{shortTime(booking.shifts.ends_at)}</p></button> : null) : <p className="rounded-2xl bg-slate-50 p-5 text-sm text-slate-500">No upcoming bookings right now.</p>}</div></section>\n      </div> : <div className="grid lg:grid-cols-[minmax(0,1.45fr)_minmax(340px,.75fr)]">'''

if old_calendar_open not in text:
    raise SystemExit('Calendar grid opening not found')
text = text.replace(old_calendar_open, new_calendar_open, 1)

old_close = '''        </aside>\n      </div>\n    </section>'''
new_close = '''        </aside>\n      </div>}\n    </section>'''
if old_close not in text:
    raise SystemExit('Calendar grid closing not found')
text = text.replace(old_close, new_close, 1)

path.write_text(text)
print('Professional portal now uses Today/Next plus Calendar/List, matching the office portal format')
